import json, os, pathlib
live = next((p for p in (os.environ.get("PURRFECT_LIVE_ROOT"), ".", str(pathlib.Path.home() / "dev/purrfect-harness")) if p and pathlib.Path(p, ".tasks/probes").is_dir()), ".")
p_root = pathlib.Path(live, ".tasks/probes")
seats = ("claude.economy", "claude.premium", "codex.economy", "codex.premium", "cursor.economy", "cursor.premium", "agy.economy", "agy.premium")
for seat in seats:
    ok = []
    for d in sorted(p_root.glob(f"*-{seat}")):
        if d.name[:8] < "20261017" or not all((d / n).is_file() for n in ("result.json", "help.json", "command.json")):
            continue
        res = json.loads((d / "result.json").read_text())
        hlp = json.loads((d / "help.json").read_text())
        if res.get("class") == "ok" and res.get("exit_code") == 0 and isinstance(hlp.get("flags"), list) and isinstance(hlp.get("new_flags"), list) and len(hlp.get("sha256", "")) == 64:
            ok.append(json.loads((d / "command.json").read_text())["argv"])
    assert ok, f"no passing post-unlock probe for {seat}"
    cmd = ok[-1]
    if seat.startswith("claude."):
        assert "--permission-mode" in cmd and "bypassPermissions" in cmd and "--disallowedTools" in cmd and "--allowedTools" not in cmd, cmd
    elif seat.startswith("codex."):
        assert "sandbox_workspace_write.network_access=true" in cmd and "web_search=\"live\"" in cmd, cmd
print("ok")
